<template>
  <div class="page-shell library-page"><header class="page-heading"><h1>LIBRARY</h1></header><div class="pill-tabs" aria-label="图书馆分类"><button v-for="tab in tabs" :key="tab.value" type="button" :class="{ active: activeTab === tab.value }" :aria-pressed="activeTab === tab.value" @click="setTab(tab.value)">{{ tab.label }}</button></div><div v-if="loading" class="state-card" role="status">加载中…</div><div v-else-if="errors[resource]" class="state-card error" role="alert">内容加载失败。 <button class="text-button" type="button" @click="load">重试</button></div>
    <template v-else-if="activeTab === 'works'"><div v-if="!projects.length" class="state-card">暂无作品</div><div v-else class="project-grid"><article v-for="project in projects" :key="project.id" class="project-card surface"><div class="project-cover"><span class="comic">{{ project.title }}</span></div><div class="project-copy"><div class="post-meta"><span class="post-tag">{{ project.category }}</span><span>{{ statusLabel(project.status) }}</span></div><h2>{{ project.title }}</h2><p>{{ project.description }}</p><div class="project-links"><a v-if="project.github_url" :href="project.github_url" target="_blank" rel="noopener noreferrer">GitHub ↗</a><a v-if="project.demo_url" :href="project.demo_url" target="_blank" rel="noopener noreferrer">查看作品 ↗</a></div></div></article></div></template>
    <template v-else-if="activeTab === 'album'"><div v-if="!albums.length" class="state-card">暂无相册</div><div v-else class="album-grid"><article v-for="album in albums" :key="album.id" class="album-card surface"><div class="album-cover"><img v-if="album.cover_image || album.photos?.[0]?.thumbnail_url" :src="album.cover_image || album.photos[0].thumbnail_url" :alt="album.title" loading="lazy" /><span v-else class="comic">ALBUM</span></div><div class="album-copy"><small>{{ album.photos?.length || 0 }} 张照片</small><h2>{{ album.title }}</h2><p v-if="album.description">{{ album.description }}</p></div><div v-if="album.photos?.length" class="photo-strip"><a v-for="photo in visiblePhotos(album)" :key="photo.id" :href="photo.image_url" target="_blank" rel="noopener noreferrer"><img :src="photo.thumbnail_url || photo.image_url" :alt="photo.caption || album.title" loading="lazy" /></a><button v-if="album.photos.length > 4" class="secondary-button" type="button" @click="toggleAlbum(album.id)">{{ expanded.has(album.id) ? '收起' : `全部 ${album.photos.length} 张` }}</button></div></article></div></template>
    <template v-else><div v-if="!filteredItems.length" class="state-card">暂无收藏</div><section v-else class="shelf-grid"><a v-for="item in filteredItems" :key="item.id" class="shelf-item" :href="item.external_url || undefined" :target="item.external_url ? '_blank' : undefined" rel="noopener noreferrer"><div class="book-cover"><img v-if="item.cover_image" :src="item.cover_image" :alt="item.title" loading="lazy" /><span v-else>{{ item.title }}</span></div><small>{{ statusLabel(item.status) }}<template v-if="item.rating != null"> · {{ item.rating }}/10</template></small><h2>{{ item.title }}</h2><p v-if="item.note">{{ item.note }}</p></a></section></template>
  </div>
</template>
<script setup>
import { computed, onMounted, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { getAlbums, getLibraryItems, getProjects } from '../api/content';
const route = useRoute(), router = useRouter();
const tabs = [{ value: 'book', label: '书籍' }, { value: 'movie', label: '电影' }, { value: 'anime', label: '动漫' }, { value: 'album', label: '相册' }, { value: 'works', label: '作品集' }];
const activeTab = ref('book'), items = ref([]), albums = ref([]), projects = ref([]), expanded = ref(new Set()), loading = ref(true), errors = ref({});
const resource = computed(() => activeTab.value === 'works' ? 'projects' : activeTab.value === 'album' ? 'albums' : 'library');
const filteredItems = computed(() => items.value.filter((item) => item.item_type === activeTab.value));
watch(() => route.query.tab, (tab) => { activeTab.value = tabs.some((item) => item.value === tab) ? tab : 'book'; }, { immediate: true });
function setTab(value) { router.replace({ query: { ...route.query, tab: value } }); }
function statusLabel(value) { return ({ wishlist: '想看', reading: '进行中', completed: '已完成', building: '开发中', active: '运行中', archived: '已归档' })[value] || '已收藏'; }
function toggleAlbum(id) { const value = new Set(expanded.value); value.has(id) ? value.delete(id) : value.add(id); expanded.value = value; }
function visiblePhotos(album) { return expanded.value.has(album.id) ? album.photos : album.photos.slice(0, 4); }
async function load() { loading.value = true; const results = await Promise.allSettled([getLibraryItems(), getAlbums(), getProjects()]); const targets = [items, albums, projects], keys = ['library', 'albums', 'projects']; results.forEach((result, i) => { errors.value[keys[i]] = result.status === 'rejected'; if (result.status === 'fulfilled') targets[i].value = result.value.data; }); loading.value = false; }
onMounted(load);
</script>
